template.query:
mutation BulkCreateUnique($input1: CreateNodeInput!, $input2: CreateNodeInput!) {
        todo1: createNode(input: $input1) {
          success
          node {
            id
            content
            createdAt
          }
          errors {
            message
            field
          }
        }
        todo2: createNode(input: $input2) {
          success
          node {
            id
            content
            createdAt
          }
          errors {
            message
            field
          }
        }
      }
